ROWS = [
dict(id="T026", x="REPORTED DISPROVED in the form stated: for every quartic Salem number β the measure ν_{1/β} has Hausdorff dimension strictly below one, so it is singular although 1/β is not a Pisot reciprocal (G. Cheng, X. Fang, X. Ma and H. Zhang, Strict Hausdorff-dimension drop for quartic Salem Bernoulli convolutions, arXiv:2610.12072, Oct 2026, unrefereed; their arXiv:2610.09902 had shown correlation dimension below one). Only two quartic Salem numbers lie in (1, 2), about 1.7221 and 1.8832; for those the drop rests on an exact interval computation with margins near 1e-22, so an independent recomputation should come before the conjecture is treated as dead. Read from the arXiv abstracts 14 Oct; flagged first by the w672 audit and checked by an agent. Which non-Pisot parameters give absolutely continuous measures stays open; the transcendental case is T075.",d="DYN", t="Absolute continuity of Bernoulli convolutions (Erdős)",
 s="For λ ∈ (1/2, 1) let ν_λ be the law of Σ_{n≥0} ±λ^n with independent fair signs. Then ν_λ is absolutely continuous for every λ that is not the reciprocal of a Pisot number (Pisot reciprocals give singular measures, Erdős 1939).",
 c="Sometimes stated as 'the Pisot reciprocals are the only exceptions'; the almost-every form is proved.",
 src="P. Erdős, On a family of symmetric Bernoulli convolutions, Amer. J. Math. 61 (1939); Y. Peres, W. Schlag and B. Solomyak, Sixty years of Bernoulli convolutions, in Fractal Geometry and Stochastics II (2000)",
 loc="Peres–Schlag–Solomyak 2000, Section 1 (to verify)",
 why="An eighty-year-old question joining probability, fractal geometry and algebraic number theory; recent progress came from entropy methods and additive combinatorics.",
 st="Absolutely continuous for almost every λ (Solomyak 1995); dimension 1 outside a set of zero Hausdorff dimension (Hochman 2014); dimension 1 for all transcendental λ (Varjú 2019); absolute continuity for Garsia numbers (Garsia 1962) and for explicit algebraic λ near 1 (Varjú 2019). Whether any non-Pisot λ gives a singular measure is open."),
dict(id="T027", d="GF", t="Conformal invariance of the loop O(n) model for 0 < n ≤ 2",
 s="For the loop O(n) model on the hexagonal lattice with 0 < n ≤ 2 at Nienhuis' critical weight x_c(n) = 1/√(2 + √(2 − n)), the loops converge to CLE(κ) with n = −2cos(4π/κ), κ ∈ (8/3, 4]. A separate and less precise conjecture: for x > x_c (the dense phase) the limit is CLE(κ′) with κ′ ∈ [4, 8).",
 src="B. Nienhuis (1982), as in T003; O. Schramm, Proc. ICM 2006, as in T002; S. Sheffield, Exploration trees and conformal loop ensembles, Duke Math. J. 147 (2009)",
 loc="Schramm ICM 2006 (to verify)",
 url="https://arxiv.org/abs/math/0602151",
 why="One conformally invariant picture for the self-avoiding walk (n = 0), the Ising model (n = 1) and the XY-type loop models (n = 2); only n = 1 is proved.",
 st="n = 1 is the Ising model's low-temperature expansion and converges to CLE(3) (Smirnov; Benoist–Hongler 2019). Macroscopic loops at x_c for n ∈ [1, 2] (Duminil-Copin–Glazman–Peled–Spinka 2021). Conformal invariance is open for n ≠ 1."),
dict(id="T028", d="SM", t="Roughening transition of the three-dimensional Ising interface",
 s="For the Ising model on Z^3 with Dobrushin boundary conditions (+ above, − below a horizontal plane) there is a roughening temperature T_R < T_c: below T_R the interface is rigid, and between T_R and T_c the variance of its height above a fixed column grows like log L in a box of side L (the height needs a definition, since the interface is not a graph).",
 src="R. L. Dobrushin, Gibbs states describing coexistence of phases for a three-dimensional Ising model, Theory Probab. Appl. 17 (1972); H. van Beijeren, Interface sharpness in the Ising system, Comm. Math. Phys. 40 (1975)",
 why="Dobrushin's rigidity theorem is a founding result of rigorous statistical mechanics; the roughening transition predicted above it has never been proved for the Ising model itself.",
 st="Rigidity at low temperature (Dobrushin 1972; van Beijeren 1975). Roughening is proved for integer-valued surface models such as the discrete Gaussian and SOS models (Fröhlich–Spencer 1981). Fine results on the low-temperature interface (Gheissari–Lubetzky 2021–23). Roughening of the Ising interface is open."),
dict(id="T029", d="DYN", t="Furstenberg's ×2 ×3 conjecture",
 s="Every Borel probability measure on R/Z that is invariant and ergodic under the joint action of x ↦ 2x and x ↦ 3x is either Lebesgue measure or supported on finitely many rational points.",
 src="H. Furstenberg, Disjointness in ergodic theory, minimal sets, and a problem in Diophantine approximation, Math. Systems Theory 1 (1967)",
 why="The model case of measure rigidity for higher-rank actions; its zero-entropy case blocks a family of conjectures of Margulis and Einsiedler–Katok–Lindenstrauss type.",
 st="Furstenberg proved the topological version (closed invariant sets). Positive entropy forces Lebesgue measure (Rudolph 1990; Johnson 1992; Host 1995). Without any invariance hypothesis, positive entropy alone pushes a measure toward Lebesgue under sublacunary multiplier sets, the semigroup generated by 2 and 3 included (Burton–Juschenko, arXiv:2610.07317, Oct 2026, with a companion paper arXiv:2610.04745). The zero-entropy case is open."),
dict(id="T030", d="BM", t="Rauch's hot spots conjecture for convex domains",
 s="For a bounded convex domain in R^2, every eigenfunction of the second Neumann eigenvalue of the Laplacian attains its maximum and minimum only on the boundary.",
 c="Rauch's original form, for general domains, is false (Burdzy–Werner 1999; Burdzy 2005); the open form is for convex domains, and in higher dimensions.",
 src="J. Rauch, Five problems: an introduction to the qualitative theory of partial differential equations, Lecture Notes in Math. 446 (1975); R. Bañuelos and K. Burdzy, On the 'hot spots' conjecture of J. Rauch, J. Funct. Anal. 164 (1999)",
 why="A clean statement about heat flow whose main proofs and counterexamples came from reflected Brownian motion and couplings.",
 st="Proved for obtuse triangles (Bañuelos–Burdzy 1999), lip domains (Atar–Burdzy 2004), convex domains with two axes of symmetry (Jerison–Nadirashvili 2000), all triangles (Judge–Mondal 2020) and further classes. Open for general convex planar domains. Update, 14 Nov 2026: the OpenAI math release (github.com/openai/math; AI-written, unrefereed) has 'Strict hot spots and absence of interior critical points on smooth simply connected planar domains' (24 Sep 2026), which claims the strict statement for smooth bounded simply connected planar domains, hence for smooth convex ones; nonsmooth convex domains remain open."),
dict(id="T031", x="SOLVED (claimed, unrefereed), 14 Nov 2026: two OpenAI math release preprints (github.com/openai/math) claim both parts: 'A directional zero-one law for finite-range-dependent random environments' (5 Oct 2026, Thm 1.1, includes iid uniformly elliptic environments in d >= 3) and 'Directional transience implies ballisticity' (23 Sep 2026, Thm 1.1, every d >= 2). The release's Lean files cover the iid statements. AI-written and unrefereed; this records the claim, not a check of the proof. Replacement row to be screened.", d="RW", t="Zero-one law and ballisticity for random walk in random environment on Z^d",
 s="For iid uniformly elliptic random walk in random environment on Z^d: (a) Kalikow's zero-one law, P(X_n·ℓ → ∞) ∈ {0, 1} for every direction ℓ; (b) Sznitman's conjecture that, for d ≥ 2, transience in direction ℓ implies ballisticity (a non-zero limiting velocity).",
 c="Dimension ranges and exact forms to verify.",
 src="O. Zeitouni, Random walks in random environment, École d'Été de Saint-Flour XXXI (2004); A.-S. Sznitman, Topics in random walks in random environment, ICTP Lecture Notes 17 (2004)",
 why="The central open problems of multidimensional RWRE, where a non-reversible walk in a random medium resists every general method.",
 st="(a) holds in d = 2 (Zerner–Merkl 2001) and is open in d ≥ 3. (b): Sznitman's conditions (T) and (T′) are equivalent to a polynomial condition (Berger–Drewitz–Ramírez 2014), and ballisticity is known under them and for small perturbations of simple random walk in d ≥ 3 (Sznitman 2003); open in general."),
dict(id="T032", d="SM", t="Bose–Einstein condensation for interacting bosons in three dimensions",
 s="The interacting Bose gas in three dimensions (for example with a repulsive pair potential), in the thermodynamic limit at fixed density, condenses at low temperature: the one-body density matrix has off-diagonal long-range order.",
 src="R. P. Feynman, Atomic theory of the λ transition in helium, Phys. Rev. 91 (1953); E. H. Lieb, R. Seiringer, J. P. Solovej and J. Yngvason, The Mathematics of the Bose Gas and its Condensation (Birkhäuser, 2005)",
 why="Condensation of interacting bosons at positive temperature is a basic physical phenomenon without a proof; the random-permutation form makes it a percolation-type question.",
 st="Proved for the ideal gas and for interactions that do not couple cycles (Süto 1993, 2002); ground-state and trapped-gas results in dilute limits (Lieb–Seiringer 2002 and later); macroscopic cycles in spatial random permutation models with special interactions (Betz–Ueltschi, arXiv:0711.1188). Open for the interacting gas at positive temperature. Update, 14 Nov 2026: the OpenAI math release (github.com/openai/math; AI-written, unrefereed) has 'Bose-Einstein condensation at positive temperature in the dilute hard-sphere gas' (5 Oct 2026), which claims a positive condensate fraction for three-dimensional hard spheres at small fixed density and low positive temperature in the thermodynamic limit; the general statement remains open.",
 c="Condensation and infinite cycles of the Feynman–Kac permutation are distinct: infinite cycles are necessary but not sufficient for condensation of the interacting gas (Süto, Phys. Scr. 2024, DOI 10.1088/1402-4896/ad8602). Macroscopic cycles are a related open question."),
dict(id="T033", d="IPS", t="Fourier's law from deterministic microscopic dynamics",
 s="A pinned, non-integrable chain of anharmonic oscillators, coupled at its two ends to Langevin heat baths at different temperatures, has a non-equilibrium steady state whose heat current is of order 1/N in the length N, that is, finite thermal conductivity; in a three-dimensional lattice the same holds for the current per unit cross-section.",
 c="One-dimensional momentum-conserving chains without pinning are expected to violate the law (anomalous conductivity); the open problem is a proof of either behaviour for a deterministic Hamiltonian system.",
 src="F. Bonetto, J. L. Lebowitz and L. Rey-Bellet, Fourier's law: a challenge to theorists, in Mathematical Physics 2000 (Imperial College Press, 2000)",
 url="https://arxiv.org/abs/math-ph/0002052",
 why="Deriving macroscopic heat conduction from microscopic deterministic dynamics is one of the oldest problems of non-equilibrium statistical mechanics.",
 st="Harmonic chains violate it (Rieder–Lebowitz–Lieb 1967). Proved for models with stochastic exchange of energy or momentum (Bernardin–Olla 2005; Basile–Bernardin–Olla, cond-mat/0509688 and cond-mat/0601544, with anomalous conductivity in 1D) and in weak-coupling limits (Dolgopyat–Liverani, arXiv:1010.3972). Open for deterministic anharmonic chains."),
dict(id="T034", d="DYN", t="Rokhlin's problem: does mixing imply mixing of all orders?",
 s="Every mixing measure-preserving transformation T of a probability space is mixing of all orders: μ(A_0 ∩ T^{−n_1}A_1 ∩ … ∩ T^{−n_k}A_k) → μ(A_0)⋯μ(A_k) as n_1 and all gaps n_{i+1} − n_i tend to infinity.",
 src="V. A. Rokhlin, On endomorphisms of compact commutative groups, Izv. Akad. Nauk SSSR Ser. Mat. 13 (1949)",
 why="Open for over seventy years; for Z^2 actions the analogue fails (Ledrappier 1978), so a proof must use something specific to a single transformation.",
 st="Proved for rank-one transformations (Kalikow 1984), finite rank (Ryzhikov 1993), mixing transformations with singular spectrum (Host 1991), and many smooth and algebraic systems. Open in general."),
dict(id="T035", x="SOLVED for one-dimensional band matrices: delocalization with Wigner–Dyson statistics and quantum unique ergodicity for W ≫ √N (Yau–Yin, arXiv:2501.01718; L. Erdős and V. Riabov, The zigzag strategy for random band matrices, arXiv:2506.06441, 2025) and exponential localization at scale W² for W² ≪ N (R. Drogin, Localization of one-dimensional random band matrices, arXiv:2508.05802, 2025) together give the conjectured transition for a large class of band matrices. Read from the arXiv abstracts 14 Oct; flagged by the w672 audit. Band matrices in dimensions two and three are T076.",d="RMT", t="The localization transition of random band matrices",
 s="For an N × N random band matrix of band width W (one-dimensional geometry), bulk eigenvectors are localized with localization length of order W² when W ≪ √N, and delocalized with GOE/GUE local statistics when W ≫ √N.",
 c="The delocalized half was proved in 2025 for W > N^{1/2+c} (Yau–Yin, arXiv:2501.01718); the localized half at the sharp scale is the open part.",
 src="Y. V. Fyodorov and A. D. Mirlin, Scaling properties of localization in random band matrices: a σ-model approach, Phys. Rev. Lett. 67 (1991); T. Spencer, Random banded and sparse matrices, in The Oxford Handbook of Random Matrix Theory (2011)",
 why="The cleanest model of the Anderson transition: one parameter interpolates between Wigner matrices and one-dimensional random Schrödinger operators.",
 st="Delocalization for W ≫ N^{1/2} (Yau–Yin, arXiv:2501.01718, for W > N^{1/2+c}; earlier N^{3/4} and N^{6/7}, Bourgade–Yau–Yin and Erdős–Knowles–Yau–Yin). Localization for W ≪ N^{1/4} (Cipolloni–Peled–Schenker–Shapiro 2023) and earlier W ≪ N^{1/8} (Schenker 2009). Open between N^{1/4} and N^{1/2}."),
dict(id="T036", d="SM", t="First-order transition of the Potts model for q ≥ 3 in three dimensions",
 s="For the q-state Potts model on Z^d with d ≥ 3 and every q ≥ 3 the phase transition is discontinuous (the magnetisation jumps at the critical temperature); in particular the 3-state Potts model on Z^3 has a first-order transition.",
 src="R. B. Potts, Some generalized order-disorder transformations, Proc. Cambridge Philos. Soc. 48 (1952); F. Y. Wu, The Potts model, Rev. Mod. Phys. 54 (1982)",
 why="Mean-field theory and numerics agree, but proofs exist only for large q or large d; q = 3, d = 3 is the standard test case.",
 st="Proved for large q (Kotecký–Shlosman 1982) and for q ≥ 3 in large d (Biskup–Chayes 2003). In d = 2 the transition is continuous for q ≤ 4 (Duminil-Copin–Sidoravicius–Tassion 2017) and discontinuous for q > 4 (Duminil-Copin–Gagnebin–Harel–Manolescu–Tassion 2016). Open for q = 3 in d = 3."),
dict(id="T037", d="GF", t="The Hausdorff dimension of Liouville quantum gravity",
 s="Determine the dimension d_γ of γ-Liouville quantum gravity, with its LQG metric, for γ ∈ (0, 2) other than γ = √(8/3), where d_γ = 4.",
 c="Watabiki's formula d_γ = 1 + γ²/4 + √((1 + γ²/4)² + γ²) was the standard prediction; rigorous bounds contradict it for small γ (Ding–Goswami, Comm. Pure Appl. Math. 72 (2019), arXiv:1610.09998, against some readings of it; bounds sharpened by Ding–Gwynne, Comm. Math. Phys. 374 (2020)), so even the conjectured value is unsettled.",
 src="Y. Watabiki, Analytic study of fractal structure of quantized surface in two-dimensional quantum gravity, Prog. Theor. Phys. Suppl. 114 (1993); J. Ding and E. Gwynne, The fractal dimension of Liouville quantum gravity: universality, monotonicity, and bounds, Comm. Math. Phys. 374 (2020)",
 url="https://arxiv.org/abs/1807.01072",
 why="The basic geometric constant of LQG; it governs distances on random planar maps decorated by critical models (for example spanning-tree-decorated maps, γ = √2).",
 st="The LQG metric exists and is unique (Ding–Dubédat–Dunlap–Falconet 2020; Gwynne–Miller 2021); d_{√(8/3)} = 4; d_γ is continuous and increasing with explicit bounds (Ding–Gwynne 2020). No other value is known."),
]
